<?php require __DIR__.'/_layout.php';x1_require_role('owner');$db=x1_db();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){try{x1_check_csrf();if(!$db)throw new RuntimeException('SQLite required');$act=(string)($_POST['act']??'add');if($act==='add'){$u=trim((string)$_POST['username']);$p=(string)$_POST['password'];$role=(string)$_POST['role'];if(strlen($p)<12)throw new RuntimeException('Password must have 12+ characters');if(!in_array($role,['owner','admin','operator','readonly'],true))throw new RuntimeException('Invalid role');$now=date('c');x1_db_exec('INSERT INTO users(id,username,password_hash,role,enabled,created_at,updated_at) VALUES(?,?,?,?,?,?,?)',[x1_id(),$u,password_hash($p,PASSWORD_DEFAULT),$role,1,$now,$now]);x1_audit('user_add',$u.' '.$role);}elseif($act==='toggle'){$id=(string)$_POST['id'];if($id===($_SESSION['user_id']??''))throw new RuntimeException('Cannot disable current account');x1_db_exec('UPDATE users SET enabled=CASE enabled WHEN 1 THEN 0 ELSE 1 END,updated_at=? WHERE id=?',[date('c'),$id]);x1_audit('user_toggle',$id);}elseif($act==='2fa'){$id=(string)$_POST['id'];$user=x1_db_one('SELECT * FROM users WHERE id=?',[$id]);if(!$user)throw new RuntimeException('User not found');if((int)$user['totp_enabled']===1){x1_db_exec('UPDATE users SET totp_enabled=0,totp_secret=NULL,updated_at=? WHERE id=?',[date('c'),$id]);}else{$secret=x1_totp_secret();x1_db_exec('UPDATE users SET totp_secret=?,totp_enabled=1,updated_at=? WHERE id=?',[$secret,date('c'),$id]);$_SESSION['last_totp_secret']=$secret;}x1_audit('user_2fa',$id);}header('Location:users.php');exit;}catch(Throwable $e){$msg=$e->getMessage();}}$rows=$db?x1_db_all('SELECT id,username,role,enabled,totp_enabled,created_at,last_login_at,last_login_ip FROM users ORDER BY created_at'):[];top(tr('Users & Roles','Utilizadores e Perfis'));?><section class="card hero"><div class=eyebrow>RBAC + TOTP</div><h2>Owner · Admin · Operator · Read Only</h2></section><?php if($msg):?><section class="notice warn"><?=h($msg)?></section><?php endif?><?php if(!empty($_SESSION['last_totp_secret'])):?><section class=notice><strong><?=tr('New TOTP secret — add it to the authenticator now:','Novo segredo TOTP — adicione agora ao autenticador:')?></strong><br><code><?=h($_SESSION['last_totp_secret'])?></code><?php unset($_SESSION['last_totp_secret']);?></section><?php endif?><section class=section><form method=post><input type=hidden name=csrf value="<?=x1_csrf()?>"><input type=hidden name=act value=add><div class=formgrid><label><?=tr('Username','Utilizador')?><input name=username required></label><label><?=tr('Password','Palavra-passe')?><input type=password name=password minlength=12 required></label><label>Role<select name=role><option value=admin>Admin</option><option value=operator>Operator</option><option value=readonly>Read Only</option><option value=owner>Owner</option></select></label></div><button><?=tr('Create user','Criar utilizador')?></button></form></section><section class=section><table><tr><th>User</th><th>Role</th><th>Status</th><th>2FA</th><th>Last login</th><th></th></tr><?php foreach($rows as $x):?><tr><td><?=h($x['username'])?></td><td><?=h($x['role'])?></td><td><?=$x['enabled']?'Enabled':'Disabled'?></td><td><?=$x['totp_enabled']?'ON':'OFF'?></td><td><?=h($x['last_login_at'])?><br><span class=muted><?=h($x['last_login_ip'])?></span></td><td><form method=post style="display:inline"><input type=hidden name=csrf value="<?=x1_csrf()?>"><input type=hidden name=act value=2fa><input type=hidden name=id value="<?=h($x['id'])?>"><button class=secondary>2FA</button></form> <form method=post style="display:inline"><input type=hidden name=csrf value="<?=x1_csrf()?>"><input type=hidden name=act value=toggle><input type=hidden name=id value="<?=h($x['id'])?>"><button class=danger><?=tr('Toggle','Alternar')?></button></form></td></tr><?php endforeach?></table></section><?php bottom();